        }
        return "";
    }

    private String extractDescription(String html) {
        // Look for meta description tag
        Pattern pattern = Pattern.compile("<meta\\s+[^>]*name\\s*=\\s*[\"']?description[\"']?\\s+[^>]*content\\s*=\\s*[\"']([^\"']*)[\"'][^>]*>", Pattern.CASE_INSENSITIVE);
