        pattern = Pattern.compile("<meta\\s+[^>]*content\\s*=\\s*[\"']([^\"']*)[\"'][^>]*name\\s*=\\s*[\"']?description[\"']?[^>]*>", Pattern.CASE_INSENSITIVE);
