        if (matcher.find()) {
            return matcher.group(1).trim();
        }

        return null;
    }

    private String getFirstNChars(String text, int n) {
        if (text == null || text.isEmpty()) {
            return "";
        }
        // Remove HTML tags for cleaner text
        String plainText = text.replaceAll("<[^>]+>", "").replaceAll("\\s+", " ").trim();
        if (plainText.length() > n) {
            return plainText.substring(0, n);
        }
        return plainText;
    }

    private String escapeJson(String value) {
        if (value == null) {
            return "";
        }
        return value.replace("\\", "\\\\")
                    .replace("\"", "\\\"")
                    .replace("\n", "\\n")
                    .replace("\r", "\\r")
                    .replace("\t", "\\t");
    }
}

